INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn08-s1-q5', 'lsn08-s1', 5, 'アップルパイ：＿＿個', '[]'::jsonb, '3');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn08-s1-q6', 'lsn08-s1', 6, 'ハンバーガー：＿＿個', '[]'::jsonb, '2');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l1', 'lsn08-s1', 1, 'A', 10259, 16902, 'この辞書はいくらですか。', 'A：这本词典多少钱？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l2', 'lsn08-s1', 2, 'B', 17624, 19813, '3000円です。', 'B：3000日元。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l3', 'lsn08-s1', 3, 'A', 25648, 31947, 'この自転車はいくらですか。', 'A：这辆自行车多少钱？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l4', 'lsn08-s1', 4, 'B', 32699, 36646, '12400円です。', 'B：12400日元。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l5', 'lsn08-s1', 5, 'A', 42482, 48040, 'この手帳はいくらですか。', 'A：这个笔记本多少钱？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l6', 'lsn08-s1', 6, 'B', 48769, 51733, '930円です。', 'B：930日元。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l7', 'lsn08-s1', 7, 'A', 57748, 63613, 'このパソコンはいくらですか。', 'A：这台电脑多少钱？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l8', 'lsn08-s1', 8, 'B', 64707, 67988, '170500円です。', 'B：170500日元。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l9', 'lsn08-s1', 9, 'A', 73982, 80798, 'すみません。ビールを４本ください。', 'A：不好意思，请给我4瓶啤酒。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l10', 'lsn08-s1', 10, 'B', 81322, 83267, 'かしこまりました。', 'B：好的。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l11', 'lsn08-s1', 11, 'A', 89248, 96772, 'アップルパイを３つと、ハンバーガーを２つください。', 'A：请给我3个苹果派和2个汉堡。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s1-l12', 'lsn08-s1', 12, 'B', 97387, 103285, 'かしこまりました。アップルパイを３つと、ハンバーグを２つですね。', 'B：好的。苹果派3个、汉堡2个，对吧。');
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn08-s2', 'listen-08', 2, 'text', '听录音，根据录音中的内容用日语填空。背景：田中询问附近哪里有便利店，并在便利店里买了东西。', 119802, 175987, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn08-s2-q1', 'lsn08-s2', 1, '田中：すみません。あのう、この（1）＿＿がありますか。', '[]'::jsonb, 'コンビニ');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn08-s2-q2', 'lsn08-s2', 2, 'A：はい、地下（2）＿＿階にあります。', '[]'::jsonb, '1');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn08-s2-q3', 'lsn08-s2', 3, '店員：ハンドソープですか。（3）＿＿棚にあります。', '[]'::jsonb, '奥|奥の');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l1', 'lsn08-s2', 1, '田中', 120102, 126026, 'すみません。あのう、この近くにコンビニがありますか。', '田中：不好意思，请问这附近有便利店吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l2', 'lsn08-s2', 2, 'A', 126027, 128695, 'はい、地下1階にあります。', 'A：有，在地下一层。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l3', 'lsn08-s2', 3, '田中', 129279, 131418, 'そうですか。ありがとうございます。', '田中：是吗，谢谢。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l4', 'lsn08-s2', 4, '田中', 134270, 137548, 'あのう、ハンドソープはどこにありますか。', '田中：那个，洗手液在哪里？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l5', 'lsn08-s2', 5, '店員', 138007, 142786, 'ハンドソープですか。この奥の棚にあります。', '店员：洗手液吗？在里面那个架子上。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l6', 'lsn08-s2', 6, '田中', 145803, 149039, 'そうですか。どうも。', '田中：是吗，谢谢。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l7', 'lsn08-s2', 7, '店員', 149284, 152134, 'いらっしゃいませ。', '店员：欢迎光临。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l8', 'lsn08-s2', 8, '田中', 152135, 157567, 'こちらのハンドソープと、このフライドチキンを２枚ください。それから、カプチーノを一つください。', '田中：请给我这个洗手液和两块炸鸡，再来一杯卡布奇诺。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l9', 'lsn08-s2', 9, '店員', 157737, 160777, 'カプチーノのサイズはどうなさいますか。', '店员：卡布奇诺要什么尺寸？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l10', 'lsn08-s2', 10, '田中', 161376, 163398, 'Lサイズでお願いします。', '田中：要大杯。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l11', 'lsn08-s2', 11, '店員', 163686, 167890, 'かしこまりました。お会計、510円です。ポイントカードはありますか。', '店员：好的。一共510日元。有积分卡吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l12', 'lsn08-s2', 12, '田中', 168352, 169552, 'はい。', '田中：有。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l13', 'lsn08-s2', 13, '店員', 169553, 171464, 'ありがとうございます。', '店员：谢谢。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l14', 'lsn08-s2', 14, '田中', 172052, 174447, 'アリペイでお願いします。', '田中：用支付宝付款。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn08-s2-l15', 'lsn08-s2', 15, '店員', 174617, 175987, 'ありがとうございます。こちら、レシートでございます。', '店员：谢谢。这是您的收据。');
